'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Modal, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './modal.css'

import { Button } from './button'
import { trapFocus } from './trap'

/**
 * Modal: the confirmation of something that cannot be undone.
 *
 * Specimen 5c is explicit about what it is for: quit, sign out, delete, leave
 * a live round. Never for information and never for a reward; those are a
 * sheet, a toast or feedback. So a modal always carries exactly two actions, a
 * destructive one first and a safe one under it, and it refuses to render
 * without the destructive one: a modal with nothing dangerous in it is a
 * misuse, and the unit test holds it to that.
 *
 * Centred in its container over a heavier scrim than the sheet's. A tap on
 * the scrim does nothing, because a player reaching for the scene behind a
 * "Quit this game?" must not answer it by accident; Escape is the safe action,
 * for the same reason. Focus lands on the safe action, is held inside while
 * open, and goes back to what had it when the modal closes.
 *
 * It performs nothing: it does not quit, sign out or delete anything. The host
 * owns both actions and the host owns `open`.
 */

export interface ModalAction {
  /** The verb of its outcome: Quit, Delete, Keep playing. */
  label: string
  onClick: () => void
}

/** How loud the warning is. Warning for leaving something behind, negative for destroying something. */
export type ModalTone = 'warning' | 'negative'

export interface ModalProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> {
  /** Rendered when true, unmounted when false. */
  open: boolean
  /** The question, in the display face: "Quit this game?". Also the dialog's name. */
  title: string
  /** The irreversible thing. First in the actions, on the negative colour, carrying `data-gs-destructive`. */
  destructiveAction: ModalAction
  /** The way back. Under the destructive one, raised; also what Escape does. */
  safeAction: ModalAction
  /** `warning` unless the action destroys something, then `negative`. */
  tone?: ModalTone
}

/** Typed in the display face, as the drawing types it. */
const MARK = '!'

export function Modal({
  open,
  title,
  destructiveAction,
  safeAction,
  tone = 'warning',
  className,
  children,
  ...rest
}: ModalProps) {
  const panelRef = React.useRef<HTMLDivElement | null>(null)

  // Read through a ref so the trap is set up once per opening rather than once
  // per render, which would move focus back to the safe action every time the
  // host re-rendered.
  const safeHandler = React.useRef(safeAction?.onClick)
  safeHandler.current = safeAction?.onClick

  React.useEffect(() => {
    if (!open || !panelRef.current) return
    const panel = panelRef.current
    return trapFocus({
      panel,
      onEscape: () => safeHandler.current?.(),
      // The safe action, found by its part rather than held in a ref, because
      // Button takes no ref of its own and a part is the contract's own handle.
      initial: panel.querySelector<HTMLElement>('[data-gs-scope="modal"][data-gs-part="dismiss"]'),
    })
  }, [open])

  if (!open) return null

  // Refused rather than rendered. A modal is only ever a confirmation of an
  // irreversible act; one with nothing irreversible in it is a sheet or a
  // toast wearing the wrong clothes, and rendering it would put a full-screen
  // scrim and a focus trap in front of information.
  if (!destructiveAction) {
    throw new Error(
      'Modal renders only to confirm something irreversible and needs a destructiveAction. ' +
        'For information use a toast; for a choice or a reward use a sheet.',
    )
  }

  return (
    <div
      {...rest}
      className={['gs-modal', className].filter(Boolean).join(' ')}
      data-gs-component="modal"
      data-gs-tone={tone}
    >
      {/* No handler: a tap outside does nothing. Emphasis rather than motion,
          so the fade is what remains of the entrance under reduced motion. */}
      <div
        className="gs-modal__scrim"
        data-gs-scope="modal"
        data-gs-part="scrim"
        data-gs-motion="fade"
        data-gs-animates="emphasis"
        aria-hidden="true"
      />
      <div
        ref={panelRef}
        className="gs-modal__panel"
        data-gs-scope="modal"
        data-gs-part="panel"
        data-gs-motion="pop"
        data-gs-animates="motion"
        role="alertdialog"
        aria-modal="true"
        aria-label={title}
        tabIndex={-1}
      >
        <span className="gs-modal__glyph gs-display-type" data-gs-scope="modal" data-gs-part="glyph" aria-hidden="true">
          {MARK}
        </span>
        <span className="gs-modal__label" data-gs-scope="modal" data-gs-part="label">
          {title}
        </span>
        {children !== undefined && children !== null ? (
          <span className="gs-modal__body" data-gs-scope="modal" data-gs-part="body">
            {children}
          </span>
        ) : null}
        <div className="gs-modal__actions" data-gs-scope="modal" data-gs-part="actions">
          <Button
            variant="destructive"
            data-gs-scope="modal"
            data-gs-part="commit"
            data-gs-destructive="true"
            onClick={destructiveAction.onClick}
          >
            {destructiveAction.label}
          </Button>
          <Button variant="secondary" data-gs-scope="modal" data-gs-part="dismiss" onClick={safeAction.onClick}>
            {safeAction.label}
          </Button>
        </div>
      </div>
    </div>
  )
}

/* Modal. Every value comes from a token; nothing here is a literal colour.

   Specimen 5c draws this and design/twins/5c.json measures ours against it: a
   heavier scrim, a surface panel centred in the container and inset from its
   sides, 3px edge, 22px round, padded 22 18 18, a 52px warning disc with a
   typed exclamation mark, the question in capitals, a line of body, then the
   destructive action on the negative colour and the safe one raised under it. */

/* The root covers its container and centres the panel with flex rather than
   with a translate, because the panel's entrance is motion.pop, which is a
   transform, and a transform used for centring would be overwritten by it. */
.gs-modal {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  /* The drawing insets the panel 20px from each side. space.6 is 24 and is the
     nearest token; 20 is a token request, space.5. */
  padding: 0 var(--gs-space-6);
}

/* The drawing scrims a modal at .7 against a sheet's .6. The scrim token is
   one alpha; a heavier one is a token request, color.scrimHeavy. */
.gs-modal__scrim {
  position: absolute;
  inset: 0;
  background: var(--gs-color-scrim);
}

.gs-modal__panel {
  position: relative;
  width: 100%;
  display: grid;
  justify-items: center;
  text-align: center;
  padding: var(--gs-space-6) var(--gs-space-4) var(--gs-space-4);

  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  color: var(--gs-color-ink);

  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-xl);
  /* The drawing casts `inset 0 2px 0 edge-high, 0 8px 0 edge, 0 24px 48px
     shadow`: the raised highlight, an 8px shelf and a soft drop. depth.raised
     is the same highlight over a 5px shelf and no drop; the drop is a token
     request, depth.modal. */
  box-shadow: var(--gs-depth-raised);
  outline: none;
}

/* The disc: 52px, which is size.chip, on the warning colour with the 3px
   edge, the mark inside it in the display face. The drawing types the mark at
   26px; the stat token is 22 and the nearest, a token request for a 26. */
.gs-modal__glyph {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--gs-size-chip);
  height: var(--gs-size-chip);
  margin-bottom: var(--gs-space-3);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-warning);
  color: var(--gs-color-on-bright);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  line-height: 1;
  text-shadow: none;
}

.gs-modal[data-gs-tone='negative'] .gs-modal__glyph {
  background: var(--gs-color-negative);
  color: var(--gs-color-on-accent);
}

/* The question: the title token in capitals with the display shadow. Arcade's
   title is Unbounded 20 at 900 against the drawing's 18; two pixels. */
.gs-modal__label {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  text-transform: uppercase;
  text-shadow: var(--gs-type-display-shadow, none);
}

/* What it costs, in the secondary ink. Tom's floor: body is never under 17px,
   so the drawing's 13 is not followed. */
.gs-modal__body {
  margin: var(--gs-space-2) 0 var(--gs-space-4);
  color: var(--gs-color-ink-secondary);
}

/* -- the actions ----------------------------------------------------------- */
.gs-modal__actions {
  width: 100%;
  display: grid;
  gap: var(--gs-space-2);
}

.gs-modal__actions > .gs-button {
  width: 100%;
}

/* The library's destructive is hollow: an outline that warns without
   inviting, which is right beside a game and wrong here. In a modal the player
   has already been asked, so the drawing fills it: the negative colour, the
   edge outline, a highlight and a shelf. depth.pressable carries the highlight
   and the shelf. The drawing's ink is white; on-accent is arcade's dark ink
   because its interactive colour is bright, so a token for ink on the negative
   colour is a request, color.onNegative. */
.gs-modal__actions > .gs-button[data-gs-variant='destructive'] {
  color: var(--gs-color-on-accent);
  background: var(--gs-color-negative);
  border-color: var(--gs-color-edge);
  box-shadow: var(--gs-depth-pressable);
}

.gs-modal__actions > .gs-button[data-gs-variant='destructive']:hover:not([aria-disabled='true']) {
  background: var(--gs-color-negative);
}

.gs-modal__actions > .gs-button[data-gs-variant='destructive']:active:not([aria-disabled='true']) {
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-pressable-pressed);
}
